// Unpack the items array and construct the clean OpenAI JSON payload in memory
const items = $json.items || [];

return items
  .filter(item => item && (item.rawText || item.title))
  .map(item => {
    const title = item.title || '';
    const rawText = item.rawText || '';

    const aiPayload = {
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: 'You are an expert automotive digital merchandising analyst. Extract vehicle lease, finance, or purchase specials from the promotional text.\n\nReturn ONLY a valid JSON object matching this schema without markdown code blocks:\n{\n  "year": 2026,\n  "make": "Hyundai",\n  "model": "Elantra",\n  "trim": "SE FWD",\n  "special_type": "lease",\n  "monthly_payment": 189,\n  "term_months": 36,\n  "down_payment": 2999,\n  "apr": null,\n  "msrp": null,\n  "title": "Lease a 2026 Hyundai Elantra SE FWD for $189 a month",\n  "disclaimer": "Full legal terms and expiration...",\n  "expiration_date": "2026-10-31"\n}\n\nRules:\n1. special_type must be: "lease", "finance", "cash", or "service".\n2. All numerical fields must be clean numbers without "$", "%", or commas.\n3. If a field is not stated in the text, set it to null.\n4. expiration_date must be in YYYY-MM-DD format if stated, else null.'
        },
        {
          role: 'user',
          content: `Extract all special offer details from this promotional snippet:\n\nTitle: ${title}\n\nContent:\n${rawText}`
        }
      ],
      response_format: { type: 'json_object' },
      max_tokens: 600,
      temperature: 0.1
    };

    return {
      json: {
        ...item,
        aiPayload
      }
    };
  });

// Clean and format AI response
const aiResponse = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  parsed = JSON.parse(aiResponse);
} catch (e) {
  const jsonMatch = aiResponse.match(/\{.*\}/s);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
}

// Access the original item from 'Prepare AI Prompts'
const originalItem = $('Prepare AI Prompts').item.json;

return {
  json: {
    staging_id: originalItem.id,
    image_hash: originalItem.imageHash || null,
    auto_approve: true,
    raw_text: originalItem.rawText || '',
    extracted_data: {
      year: parsed.year || new Date().getFullYear(),
      make: parsed.make || 'Hyundai',
      model: parsed.model || 'Special Offer',
      trim: parsed.trim || null,
      special_type: parsed.special_type || 'lease',
      monthly_payment: parsed.monthly_payment != null ? Number(parsed.monthly_payment) : null,
      term_months: parsed.term_months != null ? Number(parsed.term_months) : null,
      down_payment: parsed.down_payment != null ? Number(parsed.down_payment) : null,
      apr: parsed.apr != null ? Number(parsed.apr) : null,
      msrp: parsed.msrp != null ? Number(parsed.msrp) : null,
      title: parsed.title || originalItem.title || '',
      disclaimer: parsed.disclaimer || originalItem.disclaimer || '',
      expiration_date: parsed.expiration_date || null
    }
  }
};
